    /* ---------- Tutoriel ---------- */
    "tour.mapSelect": ["Ta carte. En raid, elle se détecte toute seule depuis les logs du jeu.", "Your map. In a raid it is detected automatically from the game logs.", "Deine Karte. Im Raid wird sie automatisch aus den Logs erkannt.", "Tu mapa. En raid se detecta solo desde los registros.", "Ваша карта. В рейде определяется сама по логам."],
    "tour.floor": ["Cartes à étages : change de niveau ici. « Auto » suit ta hauteur en jeu.", "Multi-floor maps: switch level here. “Auto” follows your in-game height.", "Mehretagen-Karten: hier die Ebene wechseln. „Auto“ folgt deiner Höhe.", "Mapas con pisos: cambia de nivel aquí. «Auto» sigue tu altura.", "Многоэтажные карты: переключайте уровень. «Авто» следит за высотой."],
    "tour.center": ["Recentrer sur ta position à chaque capture d'écran.", "Recenter on your position at every screenshot.", "Bei jedem Screenshot auf dich zentrieren.", "Recentrar en tu posición en cada captura.", "Центрировать на вашей позиции при каждом скриншоте."],
    "tour.layers": ["Les calques : extractions, conteneurs, loot, objectifs de quêtes. Décoche pour alléger.", "Layers: extracts, containers, loot, quest objectives. Untick to declutter.", "Ebenen: Ausgänge, Behälter, Loot, Auftragsziele. Zum Ausblenden abwählen.", "Capas: extracciones, contenedores, loot, objetivos. Desmarca para aligerar.", "Слои: выходы, контейнеры, лут, цели. Отключайте лишнее."],
    "tour.quests": ["Tes quêtes, synchronisées avec le jeu.", "Your quests, synced with the game.", "Deine Aufträge, mit dem Spiel synchronisiert.", "Tus misiones, sincronizadas con el juego.", "Ваши задания, синхронизированные с игрой."],
    "tour.items": ["La base d'objets : prix, marchand, hideout, emplacements.", "The item database: price, trader, hideout, spawns.", "Die Gegenstandsdatenbank: Preis, Händler, Versteck, Fundorte.", "La base de objetos: precio, comerciante, refugio, ubicaciones.", "База предметов: цена, торговец, убежище, места."],
    "tour.hideout": ["Le hideout : fixe tes niveaux et vois ce qu'il te manque.", "Your hideout: set your levels and see what you are missing.", "Dein Versteck: Stufen einstellen und sehen, was dir fehlt.", "Tu refugio: fija tus niveles y ves qué te falta.", "Убежище: укажите уровни и узнайте, чего не хватает."],
    "tour.ctrlF": ["Astuce : Ctrl+F ouvre la recherche d'objet n'importe où — prix flea, meilleur marchand, quêtes, où le trouver.", "Tip: Ctrl+F opens item search anywhere — flea price, best trader, quests, where to find it.", "Tipp: Ctrl+F öffnet die Gegenstandssuche überall — Flohmarktpreis, bester Händler, Aufträge, Fundort.", "Consejo: Ctrl+F abre la búsqueda de objetos — precio flea, mejor comerciante, misiones, dónde encontrarlo.", "Совет: Ctrl+F открывает поиск предметов — цена, торговец, задания, где найти."],
    "tour.ontop": ["Épingle la fenêtre au-dessus du jeu.", "Pins the window above the game.", "Heftet das Fenster über das Spiel.", "Fija la ventana sobre el juego.", "Закрепляет окно поверх игры."],
    "tour.mode": ["Ton mode de jeu. Chacun garde sa propre progression.", "Your game mode. Each keeps its own progress.", "Dein Spielmodus. Jeder hat eigenen Fortschritt.", "Tu modo de juego. Cada uno guarda su progreso.", "Ваш режим игры. У каждого свой прогресс."],
